'use strict';
const fs = require('node:fs');
const path = require('node:path');
const inputs = ['site-tools-base.js', 'lean-model.js', 'vendor-jspdf.js', 'pdf-fonts.js', 'estimate-pdf.js', 'lean-tools.js'];
function bundle() {
  return '/* Generated by build-lean-tools.cjs. Edit the named source modules, then rebuild. */\n' + inputs.map(file => '\n/* SOURCE: ' + file + ' */\n' + fs.readFileSync(path.join(__dirname, file), 'utf8').replace(/^\/\/# sourceMappingURL=.*$/gm, '').replace(/[ \t]+$/gm, '').trimEnd()).join('\n;\n') + '\n';
}
if (require.main === module) {
  const output = bundle();
  fs.writeFileSync(path.join(__dirname, 'site-tools.js'), output);
  console.log('Built site-tools.js (' + Buffer.byteLength(output) + ' bytes)');
}
module.exports = {bundle, inputs};
